<form class="inline-create" method="POST" action="<?php echo e(route('admin.categories.store')); ?>"><?php echo csrf_field(); ?><input name="name" placeholder="New category name" required><input name="description" placeholder="Short description"><button class="button button-dark">Add category</button></form>
